/**
 * Returneaza markup-ul unei iconite.
 *
 * @param string $name    Numele iconitei din ht_icons().
 * @param string $classes Clasele wrapper-ului.
 *
 * @return string HTML gata escapat.
 */
function ht_get_icon($name, $classes = 'ht-icon')
{
    $icons = ht_icons();

    if (!isset($icons[$name])) {
        return '';
    }

    $icon = $icons[$name];

    /* iconita poate fi doar path-ul (viewBox 20x20) sau un array cu viewBox propriu */
    $view = is_array($icon) ? $icon['view'] : '0 0 20 20';
    $path = is_array($icon) ? $icon['path'] : $icon;
    $size = (int)explode(' ', $view)[2];

    /* conturul are 1.5 in setul de baza; 'stroke' schimba grosimea, unde e nevoie */
    $width = (is_array($icon) && isset($icon['stroke'])) ? $icon['stroke'] : 1.5;

    /* setul de baza e desenat din contur; logourile de brand sunt pline */
    $paint = (is_array($icon) && !empty($icon['fill']))
        ? 'fill="currentColor"'
        : sprintf(
            'fill="none" stroke="currentColor" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round"',
            esc_attr($width)
        );

    return sprintf(
        '<span class="%1$s" aria-hidden="true"><svg width="%2$d" height="%2$d" viewBox="%3$s" %5$s '
        . 'xmlns="http://www.w3.org/2000/svg">%4$s</svg></span>',
        esc_attr($classes),
        $size,
        esc_attr($view),
        $path,
        $paint
    );
}

/**
 * Afiseaza o iconita.
 *
 * @param string $name    Numele iconitei.
 * @param string $classes Clasele wrapper-ului.
 */
function ht_icon($name, $classes = 'ht-icon')
{
    echo ht_get_icon($name, $classes); // phpcs:ignore WordPress.Security.EscapeOutput -- markup construit intern.
}
